template <typename T, typename Comp = std::less<T>>
struct FlexComp {
    // Member stores the comparison object (stateful if needed)
    Comp op{};

    // Functor operator: customizable comparison logic
    bool operator()(const T& a, const T& b) const {
        return op(a, b);
    }
};

